@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category != null ? FormatCategory(Category) : "All Recipes")</h1>

@if (Category == null)
{
    <ul>
        <li><a href="recipes/appetizers">Appetizers</a></li>
        <li><a href="recipes/main-courses">Main Courses</a></li>
        <li><a href="recipes/desserts">Desserts</a></li>
    </ul>
}
else
{
    <div class="row">
        @foreach (var recipe in GetRecipes(Category))
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Summary</p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string FormatCategory(string category) => category.Replace("-", " ")
        .Split(' ')
        .Select(w => char.ToUpper(w[0]) + w[1..])
        .Aggregate((a, b) => $"{a} {b}");

    private List<RecipeSummary> GetRecipes(string category) => category switch
    {
        "appetizers" => new()
        {
            new(1, "Bruschetta", "Classic Italian tomato and basil topping on crispy bread."),
            new(2, "Stuffed Mushrooms", "Savory cream cheese and herb stuffed mushroom caps."),
        },
        "main-courses" => new()
        {
            new(3, "Spaghetti Carbonara", "Creamy Roman pasta with pancetta and egg."),
            new(4, "Grilled Salmon", "Herb-crusted salmon fillet with lemon butter sauce."),
        },
        "desserts" => new()
        {
            new(5, "Chocolate Lava Cake", "Rich molten chocolate center in a light sponge."),
            new(6, "Tiramisu", "Classic Italian coffee-flavored layered dessert."),
        },
        _ => new()
    };

    private record RecipeSummary(int Id, string Title, string Summary);
}

@page "/recipe/{Id:int}"

<PageTitle>@(GetRecipe(Id)?.Title ?? "Recipe Not Found")</PageTitle>

@if (GetRecipe(Id) is { } recipe)
{
    <h1>@recipe.Title</h1>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <hr />
    <h4>Rate this Recipe</h4>
    <StarRating RecipeId="Id" />
}
else
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeData? GetRecipe(int id) => id switch
    {
        1 => new("Bruschetta",
            new[] { "4 slices crusty bread", "2 tomatoes, diced", "Fresh basil", "Olive oil", "Garlic clove", "Salt and pepper" },
            new[] { "Toast bread slices until golden.", "Rub with garlic clove.", "Mix diced tomatoes with basil and olive oil.", "Spoon mixture onto bread.", "Season with salt and pepper. Serve immediately." }),
        2 => new("Stuffed Mushrooms",
            new[] { "12 large mushrooms", "8 oz cream cheese", "2 cloves garlic, minced", "Fresh parsley", "Parmesan cheese", "Olive oil" },
            new[] { "Preheat oven to 375°F.", "Remove mushroom stems and hollow caps.", "Mix cream cheese, garlic, parsley, and parmesan.", "Fill mushroom caps with mixture.", "Drizzle with olive oil and bake 20 minutes." }),
        3 => new("Spaghetti Carbonara",
            new[] { "400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper", "Salt" },
            new[] { "Cook pasta in salted boiling water.", "Fry pancetta until crispy.", "Whisk egg yolks with grated cheese and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta, then egg mixture off heat.", "Add pasta water if needed for creaminess." }),
        4 => new("Grilled Salmon",
            new[] { "4 salmon fillets", "2 tbsp olive oil", "Lemon juice", "Fresh dill", "Butter", "Salt and pepper" },
            new[] { "Season salmon with salt, pepper, and olive oil.", "Preheat grill to medium-high.", "Grill skin-side down 4 minutes.", "Flip and cook 3 more minutes.", "Serve with lemon butter and fresh dill." }),
        5 => new("Chocolate Lava Cake",
            new[] { "200g dark chocolate", "150g butter", "3 eggs", "100g sugar", "50g flour", "Butter for ramekins" },
            new[] { "Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs and sugar until light.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into buttered ramekins.", "Bake 12-14 minutes until edges set but center jiggles." }),
        6 => new("Tiramisu",
            new[] { "6 egg yolks", "500g mascarpone", "300ml strong espresso", "Ladyfinger biscuits", "Cocoa powder", "2 tbsp Marsala wine" },
            new[] { "Whisk egg yolks with sugar until pale.", "Fold in mascarpone until smooth.", "Mix espresso with Marsala wine.", "Dip ladyfingers briefly in coffee mixture.", "Layer biscuits and mascarpone cream in a dish.", "Refrigerate 4 hours, dust with cocoa before serving." }),
        _ => null
    };

    private record RecipeData(string Title, string[] Ingredients, string[] Steps);
}

